import React from 'react';
import dynamic from 'next/dynamic';

import ReactLoader from 'components/common/reactLoading';

const SSOMessage = dynamic(import('components/Sso/SsoMessage'), {
  loading: () => <ReactLoader fullscreen />,
})
const SSO = ({ message, status }) => (
  <SSOMessage message={message} status={status} />
);
SSO.getInitialProps = ({ query }) => ({
  message: query.message,
  status: query.status,
});
export default SSO;
